+    assert!(turned["alignment"].is_object(), "{turned}");
+    let again = c.refused("set_part_axes", json!({ "y": [pick(&along_x)] }));
+    assert!(again.contains("already holds the part that way"), "{again}");
+    c.ok("undo", json!({}));
